"OLAYLAR_DUNYA_AVRUPA_MO:-0593-01-01:0":{"b": ["ソロンのアルコン職とセイサクテイア改革", "705d0dbf"], "d": ["債務奴隷制を廃止した改革。市民の階級が再編された。", "6d544b32"]},
