"OLAYLAR_DUNYA_AVRUPA_MO:-0656-01-01:0":{"b": ["キュプセロスがコリントスで僭主政を確立し、バッキス家が倒された", "f4f32246"], "d": ["キュプセロスはバッキス家の寡頭政を倒し、長期にわたる僭主政を確立した。", "790b64e0"]},
